begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select set_config('request.jwt.claims','{"role":"authenticated","sub":"user_ops_owner"}',true);
select public.onboard_business('Operations clinic','healthcare','GH','Africa/Accra','Main','Test address');
create temp table ops_ids as select b.id business_id,l.id location_id from public.businesses b join public.locations l on l.business_id=b.id where b.owner_user_id='user_ops_owner';
grant select on ops_ids to anon,authenticated,service_role;
select public.create_queue('a1000000-0000-4000-8000-000000000001',(select business_id from ops_ids),(select location_id from ops_ids),'Consultation',null,300,3,false,false);
select public.join_public_queue((select slug from public.queues where id='a1000000-0000-4000-8000-000000000001'),gen_random_uuid(),repeat('a',64),repeat('c',64),'Customer one',null);
select public.join_public_queue((select slug from public.queues where id='a1000000-0000-4000-8000-000000000001'),gen_random_uuid(),repeat('b',64),repeat('c',64),'Customer two',null);
create temp table ops_tickets as select id,display_number from public.tickets where queue_id='a1000000-0000-4000-8000-000000000001';grant select on ops_tickets to authenticated,service_role;
select is((select count(*) from public.notifications where type='almost_your_turn'),2::bigint,'joining enqueues one almost-turn event per eligible ticket');
set local role authenticated;
select is((public.get_queue_console('a1000000-0000-4000-8000-000000000001')->'waiting')::jsonb->0->>'customer_name','Customer one','console includes authorized customer names in FIFO order');
select ok(not(public.get_queue_console('a1000000-0000-4000-8000-000000000001')->'waiting'->0 ? 'phone'),'console omits unnecessary phone data');
select is((public.business_metrics((select business_id from ops_ids),7)->>'joins')::integer,2,'metrics derive from real tickets');
select throws_ok($$select public.operate_ticket('a1000000-0000-4000-8000-000000000001',(select id from ops_tickets where display_number='A001'),'complete',gen_random_uuid())$$,'QZ007',null,'cannot complete a waiting customer');
select lives_ok($$select public.call_next_ticket('a1000000-0000-4000-8000-000000000001','a1000000-0000-4000-8000-000000000010')$$,'call first customer');
select lives_ok($$select public.operate_ticket('a1000000-0000-4000-8000-000000000001',(select id from ops_tickets where display_number='A001'),'recall','a1000000-0000-4000-8000-000000000011')$$,'recall serving ticket');
select lives_ok($$select public.operate_ticket('a1000000-0000-4000-8000-000000000001',(select id from ops_tickets where display_number='A001'),'recall','a1000000-0000-4000-8000-000000000011')$$,'recall retry is safe');
select is((select count(*) from public.ticket_events where type='recalled'),1::bigint,'recall retry writes one audit event');
select throws_ok($$select public.operate_ticket('a1000000-0000-4000-8000-000000000001',(select id from ops_tickets where display_number='A001'),'cancel',gen_random_uuid())$$,'QZ007',null,'cannot cancel serving ticket');
select lives_ok($$select public.operate_ticket('a1000000-0000-4000-8000-000000000001',(select id from ops_tickets where display_number='A001'),'complete','a1000000-0000-4000-8000-000000000012')$$,'complete serving ticket');
select ok((select completed_at is not null from public.tickets where id=(select id from ops_tickets where display_number='A001')),'completion timestamp recorded');
select lives_ok($$select public.operate_ticket('a1000000-0000-4000-8000-000000000001',(select id from ops_tickets where display_number='A001'),'complete','a1000000-0000-4000-8000-000000000012')$$,'completion retry remains safe');
select is((select count(*) from public.ticket_events where type='completed'),1::bigint,'completion history is not duplicated');
select throws_ok($$select public.operate_ticket('a1000000-0000-4000-8000-000000000001',(select id from ops_tickets where display_number='A001'),'no_show',gen_random_uuid())$$,'QZ007',null,'completed ticket cannot become no-show');
select lives_ok($$select public.operate_ticket('a1000000-0000-4000-8000-000000000001',(select id from ops_tickets where display_number='A002'),'no_show',gen_random_uuid())$$,'waiting customer can be marked no-show');
select is((public.business_metrics((select business_id from ops_ids),7)->>'completed')::integer,1,'analytics counts completion');
select is((public.business_metrics((select business_id from ops_ids),7)->>'no_shows')::integer,1,'analytics counts no-show');
select lives_ok($$select public.operate_queue('a1000000-0000-4000-8000-000000000001','paused','a1000000-0000-4000-8000-000000000013')$$,'staff-safe pause operation');
select lives_ok($$select public.operate_queue('a1000000-0000-4000-8000-000000000001','paused','a1000000-0000-4000-8000-000000000013')$$,'pause retry idempotent');
select is((select count(*) from public.business_events where type='queue_status_changed'),1::bigint,'pause retry writes one event');
select lives_ok($$select public.save_location((select business_id from ops_ids),'a1000000-0000-4000-8000-000000000099','Second branch','Address','Africa/Accra',true)$$,'manager adds location');
select lives_ok($$select public.save_business((select business_id from ops_ids),'Updated Clinic','healthcare','Africa/Accra')$$,'owner updates profile');
select lives_ok($$select public.save_staff((select business_id from ops_ids),'user_opsstaff','staff',array['a1000000-0000-4000-8000-000000000001'::uuid])$$,'manager assigns staff');
select set_config('request.jwt.claims','{"role":"authenticated","sub":"user_opsstaff"}',true);
select lives_ok($$select public.operate_queue('a1000000-0000-4000-8000-000000000001','open',gen_random_uuid())$$,'assigned staff can resume queue');
select throws_ok($$select public.operate_queue('a1000000-0000-4000-8000-000000000001','closed',gen_random_uuid())$$,'42501',null,'staff cannot close queue');
select throws_ok($$select public.save_business((select business_id from ops_ids),'Hacked','healthcare','UTC')$$,'42501',null,'staff cannot change business settings');
select set_config('request.jwt.claims','{"role":"authenticated","sub":"user_foreign"}',true);
select throws_ok($$select public.get_queue_console('a1000000-0000-4000-8000-000000000001')$$,'42501',null,'foreign user cannot read console');
select throws_ok($$select public.business_metrics((select business_id from ops_ids),7)$$,'42501',null,'foreign user cannot read analytics');
select is(public.queuezero_receive_topic('queue:a1000000-0000-4000-8000-000000000001'),false,'foreign user cannot subscribe to staff topic');
reset role;
select set_config('request.jwt.claims','{"role":"anon"}',true);
set local role anon;
select is(public.queuezero_receive_topic('ticket:a1000000-0000-4000-8000-000000000001'),true,'opaque ticket topic supports customer capability');
select is(public.queuezero_receive_topic('business:'||(select business_id from ops_ids)::text),false,'anonymous cannot subscribe to business topics');
reset role;
select is((select count(*) from public.notifications where type='your_turn'),2::bigint,'call and distinct recall enqueue separate notices');
set local role service_role;
select is((select count(*) from public.claim_notifications(20)),4::bigint,'delivery worker claims queued notices');
select is((select count(*) from public.claim_notifications(20)),0::bigint,'leased notices cannot be claimed twice concurrently');
reset role;
set constraints all immediate;
select * from finish();rollback;
